function brand_html(bool $light=false): string {
    $logo=setting('logo');
    return '<a class="brand '.($logo?'brand-image':'brand-signature').($light?' brand-light':'').'" href="/" aria-label="'.e(setting('brand')).' ana sayfa">'.($logo?'<img class="brand-logo" src="'.e(safe_image($logo)).'" alt="'.e(setting('brand')).'">':'<span class="brand-mark"><img src="/assets/images/yurtdas-seal-v2.svg" width="40" height="44" alt=""></span><span><strong>'.e(setting('brand')).'</strong><small>'.e(setting('brand_subtitle')).'</small></span>').'</a>';
}
function head_html(string $title,string $description='',string $image='',string $canonical='',array $meta=[]): void {
    $site=setting('site_url');$base=rtrim($site,'/');
    $description=seo_plain($description?:setting('seo_description'),500);
    $canonical=$canonical?:strtok($_SERVER['REQUEST_URI']??'/', '?');
