    $robots=setting('indexing')!=='1'?'noindex,nofollow':(!empty($meta['noindex'])?'noindex,follow':'index,follow,max-image-preview:large,max-snippet:-1');
    $ogImage=safe_image(($meta['og_image']??'')?:($image?:(setting('seo_og_image')?:setting('hero_image'))));$ogType=$meta['type']??'website';
