    $graph=[jsonld_organization(),jsonld_website()];foreach($meta['jsonld']??[] as $node)$graph[]=$node;
    ?><!doctype html><html lang="tr" data-loading-animation="<?=e(setting('loading_animation','signature'))?>" data-parallax-effect="<?=e(setting('parallax_effect','gentle'))?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="/assets/motion-start.js?v=1"></script><title><?=e($title)?></title><meta name="description" content="<?=e($description)?>"><meta name="theme-color" content="<?=e($primary)?>"><meta name="robots" content="<?=$robots?>"><meta name="author" content="<?=e($meta['author']??setting('brand'))?>"><meta name="publisher" content="<?=e(setting('brand'))?>"><?php if(setting('seo_google_verification')):?><meta name="google-site-verification" content="<?=e(setting('seo_google_verification'))?>"><?php endif;if(setting('city')):?><meta name="geo.placename" content="<?=e(office_locality())?>"><meta name="geo.region" content="TR<?=setting('seo_geo_region')?'-'.e(setting('seo_geo_region')):''?>"><?php endif;if(setting('seo_geo_lat')&&setting('seo_geo_lng')):?><meta name="geo.position" content="<?=e(setting('seo_geo_lat'))?>;<?=e(setting('seo_geo_lng'))?>"><meta name="ICBM" content="<?=e(setting('seo_geo_lat'))?>, <?=e(setting('seo_geo_lng'))?>"><?php endif;?><meta property="og:type" content="<?=e($ogType)?>"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="<?=e(setting('brand'))?>"><meta property="og:title" content="<?=e($ogTitle)?>"><meta property="og:description" content="<?=e($ogDescription)?>"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="<?=e($ogTitle)?>"><meta name="twitter:description" content="<?=e($ogDescription)?>"><?php if(setting('seo_twitter')):?><meta name="twitter:site" content="<?=e(setting('seo_twitter'))?>"><?php endif;if($ogType==='article'):?><meta property="article:published_time" content="<?=e($meta['published']??'')?>"><meta property="article:modified_time" content="<?=e($meta['modified']??'')?>"><meta property="article:author" content="<?=e($meta['author']??setting('brand'))?>"><?php if(!empty($meta['section'])):?><meta property="article:section" content="<?=e($meta['section'])?>"><?php endif;endif;if($site):?><link rel="canonical" href="<?=e($base.$canonical)?>"><meta property="og:url" content="<?=e($base.$canonical)?>"><meta property="og:image" content="<?=e($base.$ogImage)?>"><meta property="og:image:alt" content="<?=e($ogTitle)?>"><meta name="twitter:image" content="<?=e($base.$ogImage)?>"><link rel="alternate" type="application/rss+xml" title="<?=e(setting('brand'))?> — Makaleler" href="<?=e($base)?>/rss.xml"><?php endif;?><link rel="icon" href="<?=e(setting('favicon')?safe_image(setting('favicon')):'/assets/images/yurtdas-favicon-v2.svg')?>"><link rel="stylesheet" href="/assets/site.css?v=6"><link rel="stylesheet" href="/assets/refined.css?v=3"><link rel="stylesheet" href="/assets/modern.css?v=3"><link rel="stylesheet" href="/assets/articles.css?v=3"><link rel="stylesheet" href="/assets/cinar.css?v=2"><link rel="stylesheet" href="/assets/mizan.css?v=1"><link rel="stylesheet" href="/assets/juris-home.css?v=18"><link rel="stylesheet" href="/assets/profile.css?v=5"><link rel="stylesheet" href="/assets/editorial.css?v=2"><link rel="stylesheet" href="/assets/mobile.css?v=3"><link rel="stylesheet" href="/assets/reference-home.css?v=2"><link rel="stylesheet" href="/assets/site-controls.css?v=2"><link rel="stylesheet" href="/assets/motion.css?v=1"><style><?=theme_css()?><?php if(setting('page_transition','signature')!=='off'):?>@view-transition{navigation:auto}@media(prefers-reduced-motion:reduce){@view-transition{navigation:none}}<?php endif;?></style><?php if($site):?><script type="application/ld+json"><?=jsonld_graph($graph)?></script><?php endif;?><script src="/assets/site.js?v=11" defer></script><script src="/assets/page-transitions.js?v=1" defer></script><script src="/assets/motion.js?v=1" defer></script></head><body data-page-transition="<?=e(setting('page_transition','signature'))?>" data-breadcrumbs="<?=e(setting('show_breadcrumbs','1'))?>" data-section-labels="<?=e(setting('show_section_labels','1'))?>" data-reading-progress="<?=e(setting('show_reading_progress','1'))?>" data-back-top="<?=e(setting('show_back_top','1'))?>" data-mobile-practice-text="<?=e(setting('show_mobile_practice_text','0'))?>" class="theme-reference header-<?=e(setting('header_layout','centered'))?> <?= $canonical === '/' ? 'home-page juris-home' : 'inner-page' ?>"><?php if(setting('loading_animation','signature')==='signature'):?><div class="site-loader" aria-hidden="true"><div class="site-loader-inner"><div class="site-loader-emblem"><svg class="site-loader-ring" viewBox="0 0 144 144" aria-hidden="true"><circle cx="72" cy="72" r="67"/></svg><img src="<?=e(safe_image(setting('logo_mark')?:setting('logo')?:'/assets/images/yurtdas-seal-v2.svg'))?>" alt="" width="112" height="112"></div><p class="site-loader-name"><?=e(setting('brand'))?></p><p class="site-loader-caption"><?=e(setting('brand_subtitle'))?></p><span class="site-loader-line"></span></div></div><?php endif;?><div class="page-transition-logo" aria-hidden="true"><img src="<?=e(safe_image(setting('logo_mark')?:setting('logo')?:'/assets/images/yurtdas-seal-v2.svg'))?>" width="80" height="88" alt=""></div><a class="skip-link" href="#main">İçeriğe geç</a><div class="reading-progress" aria-hidden="true"></div>
    <?php if(setting('show_topbar')==='1'):?><div class="topbar"><div class="container topbar-inner"><span><?=icon('pin')?> <?=e(setting('city'))?> <span class="top-separator"></span> <?=e(setting('brand_subtitle'))?></span><div><?php if(setting('email')):?><a href="mailto:<?=e(setting('email'))?>"><?=icon('mail')?><?=e(setting('email'))?></a><?php endif;?><span><?=icon('clock')?><?=e(setting('office_hours'))?></span></div></div></div>
    <?php endif;?><header class="site-header"><div class="container header-inner"><?=brand_html()?><nav class="main-nav" id="main-nav" aria-label="Ana menü"><?php if(setting('show_search','1')==='1'):?><button type="button" class="mobile-menu-search" aria-controls="search-dialog"><?=icon('search')?> <?=e(ui('search_button'))?></button><?php endif;public_navigation($canonical);?><?php if(setting('payment_enabled')==='1'&&setting('payment_url')):?><a class="mobile-menu-payment" href="<?=e(safe_url(setting('payment_url')))?>" target="_blank" rel="noopener noreferrer"><?=icon('shield')?><?=e(setting('payment_label'))?> <?=icon('arrow-up')?></a><?php endif;?></nav><div class="header-actions"><?php if(setting('show_search','1')==='1'):?><button class="search-toggle icon-button" type="button" title="Sitede ara" aria-label="Sitede ara" aria-controls="search-dialog"><?=icon('search')?></button><?php endif;?><?php if(setting('payment_enabled')==='1'&&setting('payment_url')):?><a class="header-payment" href="<?=e(safe_url(setting('payment_url')))?>" target="_blank" rel="noopener noreferrer"><?=icon('shield')?><span><?=e(setting('payment_label'))?></span></a><?php endif;?><?php if(setting('show_header_contact')==='1'):?><a class="header-contact" href="<?=e(safe_url(setting('header_contact_url')))?>"><?=e(ui('header_contact'))?> <?=icon('arrow-up')?></a><?php endif;?><button class="menu-toggle icon-button" type="button" title="Menü" aria-label="Menüyü aç" aria-expanded="false" aria-controls="main-nav"><?=icon('menu')?></button></div></div></header>
    <dialog id="search-dialog" class="search-dialog"><div class="dialog-top"><span class="eyebrow"><?=e(ui('search_eyebrow'))?></span><button class="icon-button search-close" aria-label="Aramayı kapat"><?=icon('close')?></button></div><form action="/makaleler" method="get"><label for="global-search"><?=e(ui('search_title'))?></label><div class="search-input"><input id="global-search" name="q" type="search" placeholder="<?=e(ui('search_placeholder'))?>" required maxlength="100"><button class="button" type="submit"><?=icon('search')?> <?=e(ui('search_button'))?></button></div></form><p class="muted"><?=e(ui('search_help'))?></p></dialog>
    <?php
