function footer_extra_links(): array {
    $links=[];foreach(preg_split('/\R/u',setting('footer_extra_links',FOOTER_DEFAULT_LINKS)) as $line){
        $parts=explode('|',trim($line),2);if(count($parts)!==2)continue;
        $label=trim($parts[0]);$url=trim($parts[1]);if($label!==''&&mb_strlen($label)<=100&&safe_url($url)===$url)$links[$url]=$label;
    }
    return $links;
}
function footer_html(): void {?>
    <footer class="site-footer"><div class="container footer-grid"><div class="footer-col footer-legal"><?=brand_html(true)?><h3 class="footer-title"><?=e(ui('footer_legal'))?></h3><div class="legal-notice"><?=rich_text(setting('legal_notice'))?></div><?php if(setting('geo_summary')):?><p><?=e(setting('geo_summary'))?></p><?php endif;?><?php if(setting('footer_text')):?><div class="footer-about"><?=rich_text(setting('footer_text'))?></div><?php endif;?></div><?php if(setting('show_footer_practices','1')==='1'):?><div class="footer-col"><h3 class="footer-title"><?=e(ui('footer_practices'))?></h3><ul><?php foreach(entries('practice') as $p):?><li><a href="<?=e(entry_url($p))?>"><?=e($p['title'])?></a></li><?php endforeach;?></ul></div><?php endif;if(setting('show_footer_discover','1')==='1'):?><div class="footer-col"><h3 class="footer-title"><?=e(ui('footer_discover'))?></h3><ul><?php $footerSeen=[];foreach(entries('menu') as $n):$url=safe_url($n['link']);if(isset($footerSeen[$url]))continue;$footerSeen[$url]=true;?><li><a href="<?=e($url)?>"><?=e($n['title'])?></a></li><?php endforeach;foreach(footer_extra_links() as $url=>$label):if(isset($footerSeen[$url]))continue;$footerSeen[$url]=true;?><li><a href="<?=e($url)?>"><?=e($label)?></a></li><?php endforeach;?></ul></div><?php endif;if(setting('show_footer_contact','1')==='1'):?><div class="footer-col"><h3 class="footer-title"><?=e(ui('footer_contact'))?></h3><p class="footer-line"><?=nl2br(e(setting('address')))?> <?=e(setting('seo_postal_code'))?></p><p class="footer-line"><?=e(ui('service_area'))?>: <?=e(setting('seo_service_area'))?></p><?php if(setting('phone')):?><p class="footer-line"><a href="tel:<?=e(preg_replace('/[^+0-9]/','',setting('phone')))?>"><?=e(setting('phone'))?></a></p><?php endif;?><p class="footer-line"><?=e(setting('office_hours'))?></p><?php if(setting('email')):?><p class="footer-line"><a href="mailto:<?=e(setting('email'))?>"><?=e(setting('email'))?></a></p><?php endif;?><div class="socials"><?php foreach(['linkedin'=>'LinkedIn','instagram'=>'Instagram'] as $key=>$label):if(setting($key)):?><a href="<?=e(safe_url(setting($key)))?>" target="_blank" rel="noopener noreferrer"><?=e($label)?> <?=icon('arrow-up')?></a><?php endif;endforeach;?></div></div><?php endif;?></div><div class="footer-bottom"><div class="container footer-bottom-inner"><span>© <?=date('Y')?> <?=e(setting('brand'))?>. <?=e(ui('copyright'))?></span><?php if(setting('payment_enabled')==='1'&&setting('payment_url')):?><a class="footer-payment" href="<?=e(safe_url(setting('payment_url')))?>" target="_blank" rel="noopener noreferrer"><?=icon('shield')?><?=e(setting('payment_label'))?></a><?php endif;?><a href="/iletisim"><?=e(ui('footer_contact'))?></a></div></div></footer>
    <?php if(setting('show_mobile_contact')==='1'):?><nav class="mobile-contact-bar" aria-label="Hızlı iletişim"><?php if(setting('phone')):?><a class="mobile-contact-call" href="<?=e(phone_url(setting('phone')))?>"><span class="mobile-contact-icon"><?=icon('phone')?></span><span><?=e(ui('contact_phone_label'))?></span></a><?php endif;if(setting('whatsapp')):?><a class="mobile-contact-whatsapp" href="<?=e(whatsapp_url(setting('whatsapp')))?>" target="_blank" rel="noopener noreferrer"><span class="mobile-contact-icon"><img src="/assets/images/whatsapp-brand.svg" width="24" height="24" alt=""></span><span><?=e(ui('mobile_whatsapp'))?></span></a><?php else:?><a class="mobile-contact-mail" href="/iletisim#iletisim-formu"><span class="mobile-contact-icon"><?=icon('mail')?></span><span><?=e(ui('contact_form_eyebrow'))?></span></a><?php endif;?></nav><?php endif;?>
    <?php if(setting('show_floating_contact')==='1'):?><a class="floating-contact" href="<?=e(setting('whatsapp')?whatsapp_url(setting('whatsapp')):safe_url(setting('contact_button_url')))?>" <?=setting('whatsapp')?'target="_blank" rel="noopener noreferrer"':''?>><?=icon(setting('whatsapp')?'whatsapp':'mail')?> <span><?=e(ui('floating_contact'))?></span></a><?php endif;?><button class="back-top icon-button" aria-label="Sayfanın başına dön"><?=icon('arrow-up')?></button></body></html><?php }
