    <section class="contact-band" data-home-section="contact" style="--band-image:url('<?=e(safe_image(setting('contact_band_image')))?>')"><div class="container contact-band-inner"><div><span class="eyebrow"><?=e(setting('contact_eyebrow'))?></span><h2><?=nl2br(e(setting('contact_title')))?></h2><div class="band-text"><?=rich_text(setting('contact_text'))?></div></div><a class="button button-gold" href="<?=e(safe_url(setting('contact_button_url')))?>"><?=e(setting('contact_button'))?> <?=icon('arrow-up')?></a></div></section><?php }
function article_card(array $a,bool $list=false): void {?>
    <article class="article-card <?=$list?'article-list-card':''?>"><a class="article-image" href="<?=e(entry_url($a))?>" tabindex="-1" aria-hidden="true"><img src="<?=e(safe_image($a['image']))?>" alt="" loading="lazy" width="600" height="400"><span><?=e($a['category'])?></span></a><div class="article-content"><div class="article-meta"><time datetime="<?=e(substr($a['published_at'],0,10))?>"><?=date_tr($a['published_at'])?></time><span>·</span><span><?=read_minutes($a['body'])?> <?=e(ui('reading_suffix'))?></span></div><h3><a href="<?=e(entry_url($a))?>"><?=e($a['title'])?></a></h3><?php $author=author_of($a);?><div class="article-author"><?=e(ui('author_label'))?> <?php if($author):?><a href="<?=e(entry_url($author))?>"><?=e($author['title'])?></a><?php else:?><?=e($a['author']?:setting('brand'))?><?php endif;?></div><p><?=e($a['excerpt'])?></p><a class="text-link" href="<?=e(entry_url($a))?>"><?=e(ui('read_article'))?> <?=icon('arrow')?></a></div></article><?php }
function practice_card(array $p,int $i): void {?>
